  late final _XRSLAMGetDepthFusionStats =
      _XRSLAMGetDepthFusionStatsPtr.asFunction<
        void Function(ffi.Pointer<ffi.Int>, ffi.Pointer<ffi.Int>)
      >();

  /// @brief destroy SLAM system
  void XRSLAMDestroy() {
    return _XRSLAMDestroy();
  }

  late final _XRSLAMDestroyPtr =
      _lookup<ffi.NativeFunction<ffi.Void Function()>>('XRSLAMDestroy');
  late final _XRSLAMDestroy = _XRSLAMDestroyPtr.asFunction<void Function()>();
}

