/// [pw] ★ 健康状态机(条目 16)★
///
/// "不崩溃"不等于"没坏掉"。本库有两条**静默退化**路径,错误码一条都盖不住:
/// (1) t_cam 与 t_imu 不在同一时钟域时,detail.cpp 的归并条件恒假 ⇒
/// Frame::preintegration.data 为空 ⇒ PreIntegrator::integrate 直接 return
/// false ⇒ 求解器里**一个 IMU 因子都没有**,系统退化成纯单目 SfM,
/// 却照常返回 XRSLAM_STATE_TRACKING_SUCCESS。
/// (2) landmark 发布循环只判 TT_VALID,而未三角化的 track 会带着
/// inv_depth = 0(=> ±Inf)或 -1.0(=> 相机背后的有限垃圾点)被发布。
/// XRSLAMHealth 就是把这两件事(以及时间戳自检的计数)变成**可读数字**。
///
/// 约束:
/// - 纯 C 可编译;字段只追加、不重排、不删除;sizeof 由 static_assert 钉住。
/// - 出参无条件先清零(GetHealth 的第一件事就是 memset)。
/// - 一律 int32_t / int64_t / double,不用 int(ffigen 在 32/64 位上会漂)。
enum XRSLAMHealthState {
  /// !< 未 Create / 已 Destroy。
  XRSLAM_HEALTH_NOT_CREATED(0),
  XRSLAM_HEALTH_HEALTHY(1),

  /// !< 检出上述 (1):IMU 因子为零 / 域错配。
  XRSLAM_HEALTH_DEGRADED_NO_IMU(2),

  /// !< 在跟踪,但可用 landmark 数低于阈值。
  XRSLAM_HEALTH_DEGRADED_LOW_TEXTURE(3),

  /// !< SLAM 自报 TRACKING_FAIL。
  XRSLAM_HEALTH_LOST(4);

  final int value;
  const XRSLAMHealthState(this.value);

  static XRSLAMHealthState fromValue(int value) => switch (value) {
    0 => XRSLAM_HEALTH_NOT_CREATED,
    1 => XRSLAM_HEALTH_HEALTHY,
    2 => XRSLAM_HEALTH_DEGRADED_NO_IMU,
    3 => XRSLAM_HEALTH_DEGRADED_LOW_TEXTURE,
    4 => XRSLAM_HEALTH_LOST,
    _ => throw ArgumentError('Unknown value for XRSLAMHealthState: $value'),
  };
}

final class XRSLAMHealth extends ffi.Struct {
  /// !< 最近一次**被接受**的图像时间戳(已按 convention 换算)。
  @ffi.Double()
  external double last_image_timestamp;

  /// !< 最近一次被接受的 IMU 时间戳(acc 与 gyro 取较新者)。
  @ffi.Double()
  external double last_imu_timestamp;

  /// !< last_image_timestamp - last_imu_timestamp。
  @ffi.Double()
  external double last_cam_imu_delta;

  /// !< 两路都到齐的**第一时刻**记下的差值,作基线。
  @ffi.Double()
  external double baseline_cam_imu_delta;

  /// !< |delta| 的历史最大值。
  @ffi.Double()
  external double max_abs_cam_imu_delta;

  /// !< 当前生效的域错配阈值,默认 1.0 s。
  @ffi.Double()
  external double cam_imu_delta_threshold;

  /// !< |delta - baseline| 的告警阈值,默认 0.5 s。
  @ffi.Double()
  external double baseline_drift_threshold;

  /// !< |delta - baseline| 的历史最大值。
  @ffi.Double()
  external double max_abs_baseline_drift;

  /// !< 最近一次 XRSLAMRunOneFrame 的墙钟耗时(毫秒)。
  @ffi.Double()
  external double last_frame_ms;

  @ffi.Int64()
  external int image_accepted;

  @ffi.Int64()
  external int image_rejected;

  @ffi.Int64()
  external int accel_accepted;

  @ffi.Int64()
  external int accel_rejected;

  @ffi.Int64()
  external int gyro_accepted;

  @ffi.Int64()
  external int gyro_rejected;

  /// !< 按原因分桶(三路合计):时间戳 NaN/Inf。
  @ffi.Int64()
  external int reject_non_finite_ts;

  /// !< 该路时间戳未严格递增(t <= 上一个)。
  @ffi.Int64()
  external int reject_non_monotonic_ts;

  /// !< 其余参数非法(空指针 / 尺寸 / stride / channel)。
  @ffi.Int64()
  external int reject_bad_arg;

  /// !< |t_cam - t_imu| 超阈值的次数。**不拒样本**,只计数。
  @ffi.Int64()
  external int domain_mismatch_events;

  /// !< |delta - baseline| 超阈值的次数。
  @ffi.Int64()
  external int baseline_drift_events;

  /// !< XRSLAMRunOneFrame 实际跑起来的帧数。
  @ffi.Int64()
  external int frames_run;

  /// !< 归并窗口内 IMU 样本数为 0 的帧数(见下)。
  @ffi.Int64()
  external int frames_with_zero_imu;

  /// !< 影子队列溢出丢弃数;>0 本身就是域错配的强信号。
  @ffi.Int64()
  external int shadow_overflow_drops;

  /// !< XRSLAMHealthState。
  @ffi.Int32()
  external int overall;

  /// !< XRSLAMState(未创建时为 TRACKING_FAIL)。 */
  /// /*!< 最近一帧被归并进 preintegration 的 IMU 样本数 —— **C API 层的影子模型**。
  /// XRSLAMManager 用一对影子队列复刻了 detail.cpp track_imu 的归并谓词
  /// (imu.t <= frame.t 则入帧,否则派发该帧)。
  /// ⚠️ 影子模型只吃**加速度计**样本,而 detail.cpp 里一个加速度样本要么立刻
  /// 经插值进 track_imu、要么先缓存到下一枚陀螺到达时才进,还有一类
  /// (陀螺缓冲为空 / 早于最老陀螺)会被**整个丢弃**。所以本字段是"应该有几个"
  /// 的上界估计,与真值同相位但不逐帧相等。
  /// ★ 判"这一帧到底有没有用上 IMU"请优先看 `core_imu_samples`(核内直读)。
  /// 本字段的价值在于:它在**图像/IMU 根本没进核**(时间戳被闸拒、域错配导致
  /// 归并谓词恒假)时依然有数,而核内计数器那时压根不会被更新。
  /// 0 = 影子模型认为这一帧一个 IMU 因子都没有;-1 = 还没有帧被派发过。
  @ffi.Int32()
  external int slam_state;

  @ffi.Int32()
  external int imu_samples_last_frame;

  /// !< 发布循环里 TT_VALID 的总数。
  @ffi.Int32()
  external int landmarks_published;

  /// !< 三分量 isfinite **且** triangulated 的数量。
  @ffi.Int32()
  external int landmarks_usable;

  /// !< 因 ±Inf/NaN 被丢弃(inv_depth==0 除零)。
  @ffi.Int32()
  external int landmarks_rejected_non_finite;

  /// !< 有限但未三角化(inv_depth==-1,相机背后)。
  @ffi.Int32()
  external int landmarks_rejected_untriangulated;

  /// !< 最近一帧声明的 XRSLAMTimestampConvention。
  @ffi.Int32()
  external int timestamp_convention;

  /// !< 0/1:当前 |t_cam - t_imu| 是否仍超阈值。
  @ffi.Int32()
  external int domain_mismatch_active;

  /// !< 0/1:XRSLAM_ENABLE_DEBUG_INSPECTION 是否被关掉。
  @ffi.Int32()
  external int inspection_compiled_out;

  /// !< 0/1:XRSLAM_ENABLE_THREADING(有真后台线程)。 */
  /// /*!< 0/1:inspection 的 bg/ba 槽位是否真的有人写过。
  /// ⚠️ 实测:全仓**没有任何一处**写 sliding_window_current_bg /
  /// sliding_window_current_ba,所以在当前 xrslam/src 下这一位恒为 0,
  /// XRSLAMGetBias 永远返回全零而 rc == XRSLAM_OK。别把那个零当成"偏置很小"。
  @ffi.Int32()
  external int threading_enabled;

  @ffi.Int32()
  external int bias_channel_populated;

  /// !< 核内最近一帧的图像时间戳(秒)。
  @ffi.Double()
  external double core_frame_timestamp;

  /// !< 每到达一帧 +1。**两次读到同一个值 = 期间没有新帧
  /// 走到跟踪器**,是"核卡住了"最直接的判据;
  /// 0 = 从来没有帧到达过。
  @ffi.Int64()
  external int core_frame_seq;

  /// !< 累计出现 core_imu_samples == 0 的帧数。 */
  /// /*!< ★ 判"静默退化成纯单目"就看这个 ★ 该帧**真实** IMU 样本数(补桩之前)。
  /// 0 = 这一帧一个惯性观测都没有;-1 = 还没有任何帧到达跟踪器。
  @ffi.Int64()
  external int core_imu_starved_frames;

  @ffi.Int32()
  external int core_imu_samples;

  @ffi.Int32()
  external int core_imu_samples_integrated;

  /// !< 该帧检出后的关键点总数(含跟踪继承)。-1 = 未知。
  @ffi.Int32()
  external int detected_keypoints;

  /// !< 从上一帧成功传递过来的关键点数(LK + 本质矩阵 + 泊松盘之后)。
  @ffi.Int32()
  external int tracked_keypoints;

  /// !< LK 存活里通过本质矩阵几何校验的内点数。
  @ffi.Int32()
  external int inlier_keypoints;

  /// !< 滑窗最新帧看到的 VALID&TRIANGULATED&STATIC 轨迹数;
  /// -1 = 后端还没跑起来。 */
  /// /*!< 0/1:核内遥测这次到底读到没有。0 = 还没有任何帧走到 feature_tracker
  /// (core_frame_seq == 0 且 core_imu_samples == -1),此时上面 core_* 全是初值,
  /// 不要**据此判 DEGRADED_NO_IMU。
  @ffi.Int32()
  external int mapped_landmarks;

  @ffi.Int32()
  external int core_health_available;

  @ffi.Int32()
  external int latest_pose_degenerate;
}

/// @brief landmark 过滤计账。被丢掉的点必须能被数出来,否则又是一次静默失效。
final class XRSLAMLandmarkStats extends ffi.Struct {
  /// !< 发布循环里 TT_VALID 的总数(过滤前)。
  @ffi.Int32()
  external int published;

  /// !< 三分量任一 NaN/±Inf 而被丢弃。
  @ffi.Int32()
  external int rejected_non_finite;

  /// !< 有限但 triangulated == false。
  @ffi.Int32()
  external int rejected_untriangulated;

  /// !< 实际写进 out_xyz 的点数(受容量截断)。
  @ffi.Int32()
  external int returned;
}
